      "主要经营风险": "①利差损风险（投资收益率低于产品定价利率）；②退保率上升（经济压力导致退保）；③赔付率上升（自然灾害和疫情等巨灾风险）；④偿付能力充足率达标压力；⑤投资亏损风险",
      "政策与外部驱动": "偿二代二期工程、车险综合改革、银保渠道报行合一、互联网保险监管、商业养老保险税收递延政策、巨灾保险制度建设",
