      "典型融资用途": "资本补充（发行资本债/次级债）、不动产投资、基础设施债权计划、信息系统建设",
      "上下游与结算回款方式": "上游=再保险公司（分保和摊回）、银行（资金存管）；下游=投保人和被保险人。结算通过核保系统实时收保费，理赔通过银行转账赔付，再保按合约季度结算摊回",
